#!/usr/bin/env bash\nset -euo pipefail\n\n# Resolve the path to the script under test.\nSCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/../src" && pwd)"\nSCRIPT="$SCRIPT_DIR/main.sh"\n\nrun_test() {\n  local mock_date="$1"\n  local expected_output="$2"\n  local actual_output\n  actual_output=$(MOCK_DATE="$mock_date" "$SCRIPT")\n  if [[ "$actual_output" != "$expected_output" ]]; then\n    echo "FAIL: MOCK_DATE='$mock_date' expected '$expected_output' but got '$actual_output'"\n    exit 1\n  fi\n}\n\n# Test cases covering sunrise, day, and night emojis.\nrun_test "2023-01-01 05:30" "2023-01-01 05:30 🌅"\nrun_test "2023-01-01 12:00" "2023-01-01 12:00 ☀️"\nrun_test "2023-01-01 20:45" "2023-01-01 20:45 🌙"\n\necho "All tests passed."\nexit 0\n
